import os, re, statistics, requests
from flask import Flask, request, jsonify, Response

app = Flask(__name__)

SERPER_API_KEY = os.environ.get("SERPER_API_KEY", "")

def norm(s):
    return re.sub(r"[^a-z0-9]", "", (s or "").lower())

def score_result(r, brand, model, year, target_km):
    text = f"{r.get('title','')} {r.get('snippet','')}".lower()
    score = 0
    if norm(brand) in norm(text): score += 30
    if norm(model) in norm(text): score += 45
    if str(year) in text: score += 15
    # reward explicit km near target
    kms = [int(x.replace(" ", "").replace(".", "")) for x in re.findall(r"\b\d{1,3}(?:[ .]\d{3})?\s*km\b", text)]
    if kms:
        d=min(abs(k-target_km) for k in kms)
        score += max(0, 10-min(10,d/5000))
    return score

def parse_price_km(r):
    text=f"{r.get('title','')} {r.get('snippet','')}"
    prices=[]
    for m in re.findall(r"(\d{2,3}(?:[ .]\d{3})+|\d{4,6})\s*€", text):
        try:
            v=int(m.replace(" ","").replace(".",""))
            if 10000<=v<=150000: prices.append(v)
        except: pass
    kms=[]
    for m in re.findall(r"(\d{1,3}(?:[ .]\d{3})+|\d{3,6})\s*km", text.lower()):
        try:
            v=int(m.replace(" ","").replace(".",""))
            if 0<=v<=300000: kms.append(v)
        except: pass
    return (prices[0] if prices else None, kms[0] if kms else None)

