def home():
    return Response(INDEX_HTML, mimetype="text/html")

@app.post("/api/cote")
def cote():
    data=request.get_json(force=True)
    brand=data.get("brand","").strip()
    model=data.get("model","").strip()
    year=int(data.get("year"))
    km=int(data.get("km"))
    if not SERPER_API_KEY:
        return jsonify({"error":"SERPER_API_KEY manquante sur le serveur."}),500

    queries=[
        f'"{brand} {model}" {year} camping-car occasion',
        f'"{brand} {model}" {year} {km} km',
        f'site:leboncoin.fr "{brand} {model}" {year}',
        f'site:paruvendu.fr "{brand} {model}" {year}',
        f'site:hunyvers.com "{brand} {model}" {year}',
    ]
    results=[]
    for q in queries:
        resp=requests.post("https://google.serper.dev/search",
            headers={"X-API-KEY":SERPER_API_KEY,"Content-Type":"application/json"},
            json={"q":q,"gl":"fr","hl":"fr","num":10},timeout=20)
        resp.raise_for_status()
        for x in resp.json().get("organic",[]):
            results.append(x)

    # de-duplicate by URL
    uniq={}
    for r in results:
        if r.get("link"): uniq[r["link"]]=r
    rows=[]
    for r in uniq.values():
        price, rkm=parse_price_km(r)
        sc=score_result(r,brand,model,year,km)
        if price and sc>=60:
            adj=price + ((rkm-km)*0.12 if rkm is not None else 0)
            rows.append({"title":r.get("title"),"url":r.get("link"),"snippet":r.get("snippet"),
                         "price":price,"km":rkm,"adjusted":round(adj),"score":round(sc)})
    rows.sort(key=lambda x:x["score"],reverse=True)
    rows=rows[:15]

    vals=[x["adjusted"] for x in rows if x["adjusted"]]
    if len(vals)<3:
        return jsonify({"status":"insufficient","comparables":rows,
                        "message":"Moins de 3 comparables suffisamment fiables."})
    med=statistics.median(vals)
    # robust filter
    filt=[v for v in vals if med*.88<=v<=med*1.12] if len(vals)>=5 else vals
    market=round(statistics.median(filt)/100)*100
    return jsonify({"status":"ok","comparables":rows,"market":market,
                    "trade":max(0,market-8000),
                    "confidence":"Bonne" if len(filt)>=7 else "Correcte" if len(filt)>=5 else "Faible",
                    "count":len(filt)})

if __name__=="__main__":
    app.run(host="0.0.0.0",port=int(os.environ.get("PORT","8080")))
